{"id": "timeline-one-kind-of-track", "name": "One kind of track", "summary": "Any track holds any mix of clips: video, audio, a still, text, a shape, a graphic, a nest or an adjustment clip.", "page": "timeline/tracks", "anchor": "one-kind-of-track", "where": "Timeline"}
{"id": "timeline-track-stacking", "name": "Tracks stack back to front", "summary": "Tracks are layers: the top lane is front-most and the bottom lane is at the back.", "page": "timeline/tracks", "anchor": "stacking-order", "where": "Timeline"}
{"id": "timeline-current-track", "name": "The current track", "summary": "Commands that need one track use the track of the first selected clip, or the front-most track when nothing is selected.", "page": "timeline/tracks", "anchor": "the-current-track", "where": "Track menu"}
{"id": "timeline-default-track-names", "name": "Default track names", "summary": "Each track header shows the track's name, or Track N when it has none, counting up from the back track as 1.", "page": "timeline/tracks", "anchor": "track-names", "where": "Track header"}
{"id": "timeline-track-header", "name": "The track header and its switches", "summary": "Each track has a header on the left with its name and five switches: Hide Video, Mute Audio, Lock Track, Solo and the mix panel.", "page": "timeline/tracks", "anchor": "the-track-header", "where": "Track header: eye, speaker, lock, headphones, sliders"}
{"id": "timeline-new-track", "name": "New Track", "summary": "Adds an empty track at the front, as the top lane.", "page": "timeline/manage-tracks", "anchor": "new-track", "where": "Track ▸ New Track", "keys": "⇧⌘N"}
{"id": "timeline-new-track-by-drop", "name": "Make a track by dropping past the stack", "summary": "Dragging clips above the top lane or below the bottom lane creates a new track for them.", "page": "timeline/manage-tracks", "anchor": "drop-past-the-stack", "where": "Drag a clip past the top or bottom lane"}
{"id": "timeline-rename-track", "name": "Rename a track", "summary": "Double-clicking a track header opens an in-place name field.", "page": "timeline/manage-tracks", "anchor": "rename-a-track", "where": "Double-click a track header"}
{"id": "timeline-reorder-tracks", "name": "Reorder tracks", "summary": "Dragging a track header up or down restacks the track.", "page": "timeline/manage-tracks", "anchor": "reorder-tracks", "where": "Drag a track header"}
{"id": "timeline-remove-track", "name": "Remove Track", "summary": "Removes the current track, or the track whose context menu you opened, asking first if it still holds clips.", "page": "timeline/manage-tracks", "anchor": "remove-track", "where": "Track ▸ Remove Track"}
{"id": "timeline-remove-empty-tracks", "name": "Remove Empty Tracks", "summary": "Drops every track that holds no clips at once.", "page": "timeline/manage-tracks", "anchor": "remove-empty-tracks", "where": "Track ▸ Remove Empty Tracks"}
{"id": "timeline-track-menu-switches", "name": "Track menu switches", "summary": "The Track menu flips the current track's Hide Video, Mute Audio, Lock Track and Solo switches.", "page": "timeline/manage-tracks", "anchor": "the-track-menu", "where": "Track ▸ Hide Video, Mute Audio, Lock Track, Solo"}
{"id": "timeline-track-context-menu", "name": "The track context menu", "summary": "Right-clicking a track header or the empty part of its lane opens a menu for that track, showing its own state.", "page": "timeline/manage-tracks", "anchor": "the-track-context-menu", "where": "Right-click or ⌃-click a track header or the empty part of its lane"}
{"id": "timeline-track-undo-steps", "name": "Track, marker and label edits undo one at a time", "summary": "Every switch flip, rename and reorder is one undo step, and Edit ▸ Undo names the edit it will reverse.", "page": "timeline/manage-tracks", "anchor": "undo-names", "where": "Edit ▸ Undo", "keys": "⌘Z"}
{"id": "timeline-hide-video", "name": "Hide Video", "summary": "Takes a track's picture out of the preview and the export, leaving its sound playing.", "page": "timeline/hide-and-lock-tracks", "anchor": "hide-video", "where": "Track header: eye / struck-through eye"}
{"id": "timeline-lock-track", "name": "Lock Track", "summary": "Protects a track: its clips cannot be dragged, trimmed, slipped or rolled, and ripples, inserts and range edits leave it alone.", "page": "timeline/hide-and-lock-tracks", "anchor": "lock-track", "where": "Track header: open / closed padlock"}
{"id": "timeline-track-height", "name": "Timeline Track Height", "summary": "Picks small, medium or large track rows for every project.", "page": "timeline/track-height", "anchor": "small-medium-large", "where": "Timeline bar: S / M / L"}
{"id": "timeline-height-follows-contents", "name": "Height follows what a track holds", "summary": "A track's height also depends on what it holds, so sound-only and text tracks draw shorter than picture tracks.", "page": "timeline/track-height", "anchor": "height-follows-contents", "where": "Timeline"}
{"id": "timeline-clip-block", "name": "The clip block", "summary": "Each clip draws as one rounded block with a thin border, so its ends are always visible.", "page": "timeline/reading-a-clip", "anchor": "the-clip-block", "where": "Timeline lanes"}
{"id": "timeline-clip-colour-by-kind", "name": "Colour by kind", "summary": "A clip's colour shows its kind.", "page": "timeline/reading-a-clip", "anchor": "colour-by-kind", "where": "Timeline lanes"}
{"id": "timeline-clip-name-strip", "name": "The name strip", "summary": "The top strip of a clip carries a kind symbol, its name, its label dot, and a link mark when it is linked.", "page": "timeline/reading-a-clip", "anchor": "the-name-strip", "where": "Timeline lanes"}
{"id": "timeline-clip-filmstrip", "name": "Filmstrip thumbnails", "summary": "Thumbnails run along the picture part of a video or image clip, under a wash of its colour.", "page": "timeline/reading-a-clip", "anchor": "filmstrip", "where": "Timeline lanes"}
{"id": "timeline-clip-waveform", "name": "The waveform", "summary": "The sound of a clip with audio is drawn as a waveform, below the filmstrip when it has both, following its source time through speed and ramps.", "page": "timeline/reading-a-clip", "anchor": "waveform", "where": "Timeline lanes"}
{"id": "timeline-clip-fade-handles", "name": "Fade handles", "summary": "Small white squares at the top corners of the audio part of a clip set its fades when dragged inward.", "page": "timeline/reading-a-clip", "anchor": "fade-handles", "where": "Drag a fade handle on a clip"}
{"id": "timeline-clip-selected-ring", "name": "The selection ring and trim grips", "summary": "A selected clip gets a 2 pt coral ring and trim grips at both ends, and most commands act on it.", "page": "timeline/reading-a-clip", "anchor": "selected-clips", "where": "Timeline lanes"}
{"id": "timeline-clip-dimmed", "name": "Dimmed clips", "summary": "A clip on a hidden track, or with both its picture and sound switched off, draws dimmed.", "page": "timeline/reading-a-clip", "anchor": "dimmed-clips", "where": "Timeline lanes"}
{"id": "timeline-clip-adjustment-look", "name": "How an adjustment clip looks", "summary": "An adjustment clip is a plain rose block with only its name strip and action lane.", "page": "timeline/reading-a-clip", "anchor": "adjustment-clips", "where": "Timeline lanes"}
{"id": "timeline-ruler-ticks", "name": "Adaptive ruler ticks and labels", "summary": "The ruler's ticks and labels adapt to the zoom, from single frames up to hours.", "page": "timeline/ruler-and-playhead", "anchor": "ticks-and-labels", "where": "Timeline ruler"}
{"id": "timeline-playhead-mark", "name": "The playhead", "summary": "The playhead is a coral line down every track with a triangle head on the ruler.", "page": "timeline/ruler-and-playhead", "anchor": "the-playhead", "where": "Timeline ruler"}
{"id": "timeline-playhead-edit-point", "name": "The playhead is where edits happen", "summary": "Split, trim to playhead, freeze frame, paste, insert and overwrite all work at the playhead.", "page": "timeline/ruler-and-playhead", "anchor": "the-edit-point", "where": "Timeline playhead"}
{"id": "timeline-ruler-scrub", "name": "Click or drag the ruler to scrub", "summary": "Clicking the ruler moves the playhead there, and dragging along it scrubs while you hear the sound under the playhead.", "page": "timeline/ruler-and-playhead", "anchor": "scrub-on-the-ruler", "where": "Click or drag on the ruler"}
{"id": "timeline-lane-clicks-leave-playhead", "name": "A click in a lane leaves the playhead", "summary": "A click in a lane doesn't move the playhead; it starts a marquee selection.", "page": "timeline/ruler-and-playhead", "anchor": "lane-clicks", "where": "Click in a lane"}
{"id": "timeline-follows-playhead", "name": "The timeline follows the playhead", "summary": "When the playhead leaves the visible part, the view moves so it sits about a third of the way in.", "page": "timeline/ruler-and-playhead", "anchor": "following-the-playhead", "where": "Automatic"}
{"id": "timeline-play-pause", "name": "Play and pause", "summary": "Space, or the Play and Pause button, starts and stops playback from wherever the focus is.", "page": "timeline/playback", "anchor": "play-and-pause", "where": "Toolbar transport: Play / Pause", "keys": "Space"}
{"id": "timeline-jkl-shuttle", "name": "J, K and L shuttle", "summary": "L plays forward and J plays in reverse, each further press stepping ×1 to ×2 to ×4, and K pauses.", "page": "timeline/playback", "anchor": "j-k-and-l", "where": "J", "keys": "J"}
{"id": "timeline-step-frames", "name": "Step frames", "summary": "← and → pause and move the playhead one frame; with ⇧ they move ten.", "page": "timeline/playback", "anchor": "step-frames", "where": "← / →", "keys": "←"}
{"id": "timeline-playback-end", "name": "What happens at the end", "summary": "Playback stops at the end of the timeline, and Play on an empty timeline beeps.", "page": "timeline/playback", "anchor": "at-the-end", "where": "Play"}
{"id": "timeline-look-only-redraw", "name": "Look-only edits redraw in place", "summary": "A change that only alters how something looks redraws the frame without interrupting playback.", "page": "timeline/playback", "anchor": "look-only-edits", "where": "Preview"}
{"id": "timeline-structural-rebuild", "name": "Structural edits rebuild in the background", "summary": "A move, trim or new clip rebuilds the player in the background, keeping your place and rate.", "page": "timeline/playback", "anchor": "structural-edits", "where": "Preview"}
{"id": "timeline-failed-rebuild", "name": "A failed rebuild keeps playing", "summary": "If a rebuild fails, an error shows and the previous version keeps playing.", "page": "timeline/playback", "anchor": "failed-rebuild", "where": "Preview"}
{"id": "timeline-edit-point-jumps", "name": "Previous and Next Edit Point", "summary": "↑ and ↓, or the transport's chevrons, jump the playhead to the previous or next edit point.", "page": "timeline/move-the-playhead", "anchor": "jump-between-edit-points", "where": "Toolbar transport: Previous Edit Point, Next Edit Point", "keys": "↑"}
{"id": "timeline-go-to-start-end", "name": "Go to Start and Go to End", "summary": "Home and End, or the transport's buttons, pause and move the playhead to the start or end of the timeline.", "page": "timeline/move-the-playhead", "anchor": "go-to-the-start-or-end", "where": "Toolbar transport: Go to Start, Go to End", "keys": "Home"}
{"id": "timeline-timecode-field", "name": "Type a timecode to jump", "summary": "The toolbar shows the playhead's time; click it, type a time and press Return to pause and jump there.", "page": "timeline/move-the-playhead", "anchor": "type-a-time-to-jump", "where": "Toolbar timecode field: click, type, Return or click away"}
{"id": "timeline-duration-readout", "name": "The duration readout", "summary": "Beside the time, the toolbar shows a slash and the duration of what the timeline shows.", "page": "timeline/move-the-playhead", "anchor": "read-the-duration", "where": "Toolbar, after the timecode field"}
{"id": "timeline-set-playhead-tool", "name": "Move the playhead with an agent", "summary": "set_playhead moves the playhead and seeks the preview, as view state with no undo step.", "page": "timeline/move-the-playhead", "anchor": "with-an-agent"}
{"id": "timeline-loop", "name": "Loop playback", "summary": "The Loop button repeats the in/out range when one is set, otherwise the whole timeline.", "page": "timeline/loop", "anchor": "turn-loop-on", "where": "Toolbar transport: Loop (the repeat button)"}
{"id": "timeline-pinch-zoom", "name": "Pinch and ⌥ or ⌘ scroll to zoom", "summary": "A trackpad pinch, or scrolling with ⌥ or ⌘ held, zooms the timeline about the pointer, keeping the time under it in place.", "page": "timeline/zoom-and-scroll", "anchor": "zoom-about-the-pointer", "where": "Pinch over the timeline"}
{"id": "timeline-zoom-slider", "name": "The zoom slider", "summary": "The slider in the timeline bar zooms about the middle of the view, on a log scale across the whole zoom range.", "page": "timeline/zoom-and-scroll", "anchor": "use-the-zoom-slider", "where": "Timeline bar: −, slider, +, Fit (⇔)"}
{"id": "timeline-zoom-buttons", "name": "Zoom Out and Zoom In buttons", "summary": "The − and + buttons step the timeline zoom about the middle of the view.", "page": "timeline/zoom-and-scroll", "anchor": "step-with-the-zoom-buttons", "where": "Timeline bar: − / +"}
{"id": "timeline-fit-timeline", "name": "Fit Timeline", "summary": "Fits the whole project across the timeline pane and scrolls to the start.", "page": "timeline/zoom-and-scroll", "anchor": "fit-the-whole-project", "where": "View ▸ Fit Timeline", "keys": "⇧Z"}
{"id": "timeline-zoom-range", "name": "Starting zoom and zoom range", "summary": "A window opens at 42 pt per second, not fitted, and the zoom runs from hours to single frames on screen.", "page": "timeline/zoom-and-scroll", "anchor": "how-far-it-zooms", "where": "Timeline"}
{"id": "timeline-plain-scroll", "name": "Scroll the timeline", "summary": "A plain scroll or two-finger swipe moves the timeline, with the track headers and ruler staying in place.", "page": "timeline/zoom-and-scroll", "anchor": "scroll-the-timeline", "where": "Scroll or two-finger swipe over the timeline"}
{"id": "timeline-click-select", "name": "Click to select", "summary": "Clicking a clip selects it alone.", "page": "timeline/selecting-clips", "anchor": "click-a-clip", "where": "Click a clip"}
{"id": "timeline-shift-click-select", "name": "⇧-click to add or remove", "summary": "⇧-click toggles a clip in or out of the selection.", "page": "timeline/selecting-clips", "anchor": "add-or-remove-a-clip", "where": "⇧-click a clip"}
{"id": "timeline-marquee-select", "name": "Marquee selection", "summary": "Dragging from empty timeline space draws a band that selects every clip it touches; ⇧-drag adds to the selection.", "page": "timeline/selecting-clips", "anchor": "drag-a-marquee", "where": "Drag from a gap in a lane, the strip under the ruler or the space below the last lane"}
{"id": "timeline-clear-selection", "name": "Clear the selection", "summary": "A bare click on empty timeline space clears the selection.", "page": "timeline/selecting-clips", "anchor": "clear-the-selection", "where": "Click an empty lane, or above or below the lanes"}
{"id": "timeline-select-all", "name": "Select All", "summary": "Selects every clip in the timeline being edited, on locked tracks too.", "page": "timeline/selecting-clips", "anchor": "select-all-the-clips", "where": "Edit ▸ Select All", "keys": "⌘A"}
{"id": "timeline-select-after-playhead", "name": "Select After Playhead", "summary": "Selects every clip whose start is at or after the playhead.", "page": "timeline/selecting-clips", "anchor": "select-everything-after-the-playhead", "where": "Edit ▸ Select After Playhead", "keys": "⌥⌘A"}
{"id": "timeline-select-all-on-track", "name": "Select All on Track", "summary": "Selects every clip on the current track, or on the track whose header you ⌥-click.", "page": "timeline/selecting-clips", "anchor": "select-all-the-clips-on-a-track", "where": "Edit ▸ Select All on Track"}
{"id": "timeline-selection-block", "name": "The selection block", "summary": "The left end of the timeline bar names what is selected.", "page": "timeline/selecting-clips", "anchor": "see-whats-selected", "where": "Timeline bar, left end"}
{"id": "timeline-selection-is-view-state", "name": "Selection is view state", "summary": "A selection is never an undo step and is not saved.", "page": "timeline/selecting-clips", "anchor": "how-a-selection-behaves"}
{"id": "timeline-snap-targets", "name": "What a drag snaps to", "summary": "Moves, trims, rolls, marker drags and ruler scrubs jump to a nearby target.", "page": "timeline/snapping", "anchor": "what-a-drag-snaps-to", "where": "Timeline drags, snapping on"}
{"id": "timeline-snap-toggle", "name": "Turn snapping on and off", "summary": "N, the Snap box or View ▸ Snapping turn snapping on or off for the timeline and the canvas together.", "page": "timeline/snapping", "anchor": "turn-snapping-on-or-off", "where": "N", "keys": "N"}
{"id": "timeline-snap-suspend", "name": "Hold ⌘ to suspend snapping", "summary": "Holding ⌘ turns snapping off for the current drag, on the timeline and on the canvas.", "page": "timeline/snapping", "anchor": "turn-snapping-off-for-one-drag", "where": "Hold ⌘ during any drag that snaps", "keys": "⌘ while dragging"}
{"id": "timeline-snap-guide", "name": "The snap guide line", "summary": "When a drag snaps, a thin vertical guide line across the timeline marks what it caught.", "page": "timeline/snapping", "anchor": "see-what-a-drag-caught", "where": "Timeline drags"}
{"id": "timeline-frame-accurate-drags", "name": "Drags land on whole frames", "summary": "A drag that doesn't snap still lands on a whole frame.", "page": "timeline/snapping", "anchor": "drags-land-on-whole-frames", "where": "Timeline drags"}
{"id": "timeline-what-never-snaps", "name": "What never snaps", "summary": "A slip never snaps, and a media row dropped on a lane lands on the nearest frame at the pointer without snapping to edges.", "page": "timeline/snapping", "anchor": "what-never-snaps", "where": "Drop a Media tab row on a lane"}
{"id": "timeline-add-marker", "name": "Add a marker", "summary": "Drops a marker at the playhead.", "page": "timeline/markers", "anchor": "add-a-marker", "where": "M", "keys": "M"}
{"id": "timeline-marker-flags", "name": "Marker flags", "summary": "Each marker draws as a small flag with a line down the ruler, in its colour.", "page": "timeline/markers", "anchor": "add-a-marker", "where": "Timeline ruler"}
{"id": "timeline-move-marker", "name": "Move a marker", "summary": "Dragging a flag along the ruler moves the marker.", "page": "timeline/markers", "anchor": "move-rename-and-remove-a-marker", "where": "Drag a marker's flag"}
{"id": "timeline-rename-marker", "name": "Rename a marker", "summary": "Double-click a flag to type in place, or type in its row in the Document tab.", "page": "timeline/markers", "anchor": "move-rename-and-remove-a-marker", "where": "Double-click a marker flag"}
{"id": "timeline-next-previous-marker", "name": "Next and Previous Marker", "summary": "Pause playback and jump the playhead to the next or previous marker.", "page": "timeline/markers", "anchor": "jump-between-markers", "where": "Mark ▸ Next Marker"}
{"id": "timeline-markers-list", "name": "The Document tab's Markers list", "summary": "The Document tab lists every marker in time order, each with its time, name, Chapter, Go and Delete.", "page": "timeline/markers", "anchor": "the-markers-list", "where": "Document tab: Markers"}
{"id": "timeline-marker-go", "name": "Go to a marker from its row", "summary": "A marker row's Go button moves the playhead to it.", "page": "timeline/markers", "anchor": "jump-between-markers", "where": "Document tab: Markers row, Go"}
{"id": "timeline-remove-marker", "name": "Remove a marker", "summary": "A marker row's Delete button removes it.", "page": "timeline/markers", "anchor": "move-rename-and-remove-a-marker", "where": "Document tab: Markers row, Delete"}
{"id": "timeline-chapter-markers", "name": "Chapter markers", "summary": "A marker with Chapter ticked becomes a chapter of the exported movie, and its flag fills.", "page": "timeline/markers", "anchor": "make-a-chapter", "where": "Document tab: Markers row, Chapter"}
{"id": "timeline-marker-colours", "name": "Marker colours", "summary": "A marker's colour is set only through an agent.", "page": "timeline/markers", "anchor": "marker-colours"}
{"id": "timeline-markers-in-a-nest", "name": "Markers while a nest is open", "summary": "Markers belong to the whole timeline, so an open nest hides them from the ruler.", "page": "timeline/markers", "anchor": "good-to-know", "where": "Timeline while a nest is open"}
{"id": "timeline-range", "name": "The in/out range", "summary": "A span of the timeline, shaded across the ruler and lanes, that other commands act on.", "page": "timeline/in-out-range", "anchor": "what-the-range-is", "where": "Timeline ruler and lanes"}
{"id": "timeline-set-in", "name": "Set In", "summary": "Sets the in point at the playhead.", "page": "timeline/in-out-range", "anchor": "set-in", "where": "Mark ▸ Set In", "keys": "I"}
{"id": "timeline-set-out", "name": "Set Out", "summary": "Sets the out point at the playhead.", "page": "timeline/in-out-range", "anchor": "set-out", "where": "Mark ▸ Set Out", "keys": "O"}
{"id": "timeline-clear-range", "name": "Clear Range", "summary": "Clears the in/out range.", "page": "timeline/in-out-range", "anchor": "clear-range", "where": "Mark ▸ Clear Range", "keys": "⌥X"}
{"id": "timeline-crossing-range-points", "name": "Crossing points", "summary": "Setting an in point after the out point moves the out point to match, and the other way round.", "page": "timeline/in-out-range", "anchor": "crossing-points", "where": "Mark ▸ Set In / Set Out"}
{"id": "timeline-range-is-view-state", "name": "The range is view state", "summary": "The range is not an undo step and is not saved, and it clears on entering or leaving a nest.", "page": "timeline/in-out-range", "anchor": "the-range-isnt-saved"}
{"id": "timeline-rename-clip", "name": "Rename a clip", "summary": "A field opens over the clip's name strip so you can name it in place.", "page": "timeline/names-and-labels", "anchor": "rename-a-clip", "where": "Double-click the clip", "keys": "⇧⌘R"}
{"id": "timeline-clear-clip-name", "name": "Clear a clip's name", "summary": "The name field at the top of the Clip tab names a single clip, and emptying it clears the name back to what the clip shows.", "page": "timeline/names-and-labels", "anchor": "clear-a-name", "where": "Clip tab: header name field"}
{"id": "timeline-clip-labels", "name": "Label a clip", "summary": "Applies a colour label to every selected clip, shown as a small dot on its name strip.", "page": "timeline/names-and-labels", "anchor": "colour-labels", "where": "Clip ▸ Label ▸ Red, Orange, Yellow, Green, Blue, Purple, None"}
{"id": "timeline-set-clip-names", "name": "Names and labels for agents", "summary": "Agents set a clip's name and label through set_clip's patch.", "page": "timeline/names-and-labels", "anchor": "with-an-agent"}
{"id": "timeline-preview-pane", "name": "The preview pane", "summary": "The preview shows the frame under the playhead at canvas size, letterboxed in the middle left of the window.", "page": "timeline/preview", "anchor": "what-it-shows", "where": "Editor window, middle left"}
{"id": "timeline-preview-tags", "name": "Preview tags", "summary": "Small tags in the preview's top-left corner say which seeing switch is on: Ungraded, Selection or SDR Version.", "page": "timeline/preview", "anchor": "preview-tags", "where": "Preview, top-left"}
{"id": "timeline-preview-view-items", "name": "Other View items for the preview", "summary": "The View menu holds the other switches for the preview and points to the pages that explain them.", "page": "timeline/preview", "anchor": "other-view-items", "where": "View ▸ Safe Areas", "keys": "⌃⌘U"}
{"id": "timeline-preview-quality", "name": "Preview Quality", "summary": "Draws the preview at Full, Half or Quarter of the canvas size and scales it back up, so heavy projects play more smoothly.", "page": "timeline/preview-quality", "anchor": "full-half-quarter", "where": "View ▸ Preview Quality ▸ Full, Half, Quarter"}
