merged = {k: dict(v) for k, v in rows.items()}
for u in fx["updates"]:
    merged[u["id"]].update(u)
bad = re.compile(r"\b(refus\w*|the op|the core|answers?|ticks?|ticked|patch|view state|bare|simply|just|easily)\b", re.I)
for k, f in merged.items():
    for field in ("name", "summary", "where"):
