            print("WORD", k, field, f[field])
    if len(f["summary"]) > 140:
        print("LONG", k, len(f["summary"]))


def slug(h):
    h = h.lower().replace("'", "").replace("’", "")
    h = re.sub(r"[^\w\s-]", "", h)
    return re.sub(r"\s+", "-", h.strip())


for k, f in merged.items():
    if not f.get("anchor"):
        continue
    t = open(base + "content/docs/" + f["page"] + ".mdx").read()
    heads = {slug(m) for m in re.findall(r"^#{2,4}\s+(.+)$", t, re.M)}
    if f["anchor"] not in heads:
        print("ANCHOR", k, f["anchor"])

